546→// TestCalculateTotalTokenUsage_PerCheckpoint verifies token usage
547→// is calculated per-checkpoint, not from the full conversation.
548→// This tests the core CalculateTotalTokenUsage function which should:
549→// - From line 0: count all turns
550→// - From line N: count only turns from line N onwards
551→func TestCalculateTotalTokenUsage_PerCheckpoint(t *testing.T) {
552→	t.Parallel()
553→
554→	tmpDir := t.TempDir()
555→	transcriptPath := tmpDir + "/transcript.jsonl"
556→
557→	// Build transcript with 3 turns:
558→	// Turn 1: user + assistant (100 input, 50 output)
559→	// Turn 2: user + assistant (200 input, 100 output)
560→	// Turn 3: user + assistant (300 input, 150 output)
561→	//
562→	// Lines:
563→	// 0: user message 1
564→	// 1: assistant response 1 (100/50 tokens)
565→	// 2: user message 2
566→	// 3: assistant response 2 (200/100 tokens)
567→	// 4: user message 3
568→	// 5: assistant response 3 (300/150 tokens)
569→
570→	transcriptContent := []byte(
571→		`{"type":"user","uuid":"u1","message":{"content":"first prompt"}}` + "\n" +
572→			`{"type":"assistant","uuid":"a1","message":{"id":"m1","usage":{"input_tokens":100,"output_tokens":50}}}` + "\n" +
573→			`{"type":"user","uuid":"u2","message":{"content":"second prompt"}}` + "\n" +
574→			`{"type":"assistant","uuid":"a2","message":{"id":"m2","usage":{"input_tokens":200,"output_tokens":100}}}` + "\n" +
575→			`{"type":"user","uuid":"u3","message":{"content":"third prompt"}}` + "\n" +
576→			`{"type":"assistant","uuid":"a3","message":{"id":"m3","usage":{"input_tokens":300,"output_tokens":150}}}` + "\n",
577→	)
578→	if err := os.WriteFile(transcriptPath, transcriptContent, 0o600); err != nil {
579→		t.Fatalf("failed to write transcript: %v", err)
580→	}
581→
582→	// Test 1: From line 0 - all 3 turns = 600 input, 300 output
583→	usage1, err := CalculateTotalTokenUsage(transcriptPath, 0, "")
584→	if err != nil {
585→		t.Fatalf("CalculateTotalTokenUsage(0) error: %v", err)
586→	}
587→	if usage1.InputTokens != 600 || usage1.OutputTokens != 300 {
588→		t.Errorf("From line 0: got input=%d output=%d, want input=600 output=300",
589→			usage1.InputTokens, usage1.OutputTokens)
590→	}
591→	if usage1.APICallCount != 3 {
592→		t.Errorf("From line 0: got APICallCount=%d, want 3", usage1.APICallCount)
593→	}
594→
595→	// Test 2: From line 2 (after turn 1) - turns 2+3 only = 500 input, 250 output
596→	usage2, err := CalculateTotalTokenUsage(transcriptPath, 2, "")
597→	if err != nil {
598→		t.Fatalf("CalculateTotalTokenUsage(2) error: %v", err)
599→	}
600→	if usage2.InputTokens != 500 || usage2.OutputTokens != 250 {
601→		t.Errorf("From line 2: got input=%d output=%d, want input=500 output=250",
602→			usage2.InputTokens, usage2.OutputTokens)
603→	}
604→	if usage2.APICallCount != 2 {
605→		t.Errorf("From line 2: got APICallCount=%d, want 2", usage2.APICallCount)
606→	}
607→
608→	// Test 3: From line 4 (after turns 1+2) - turn 3 only = 300 input, 150 output
609→	usage3, err := CalculateTotalTokenUsage(transcriptPath, 4, "")
610→	if err != nil {
611→		t.Fatalf("CalculateTotalTokenUsage(4) error: %v", err)
612→	}
613→	if usage3.InputTokens != 300 || usage3.OutputTokens != 150 {
614→		t.Errorf("From line 4: got input=%d output=%d, want input=300 output=150",
615→			usage3.InputTokens, usage3.OutputTokens)
616→	}
617→	if usage3.APICallCount != 1 {
