//go:build integration

package integration

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// TranscriptBuilder builds realistic JSONL transcripts for testing.
type TranscriptBuilder struct {
	messages       []map[string]interface{}
	toolUseCounter int
}

// NewTranscriptBuilder creates a new transcript builder.
func NewTranscriptBuilder() *TranscriptBuilder {
	return &TranscriptBuilder{
		messages: make([]map[string]interface{}, 0),
	}
}

// AddUserMessage adds a user message with string content.
func (b *TranscriptBuilder) AddUserMessage(content string) *TranscriptBuilder {
	b.messages = append(b.messages, map[string]interface{}{
		"uuid":      fmt.Sprintf("user-%d", len(b.messages)+1),
		"type":      "user",
		"message":   map[string]interface{}{"content": content},
		"timestamp": time.Now().UTC().Format(time.RFC3339),
	})
	return b
}

// AddAssistantMessage adds an assistant message with text content.
func (b *TranscriptBuilder) AddAssistantMessage(content string) *TranscriptBuilder {
	b.messages = append(b.messages, map[string]interface{}{
		"uuid": fmt.Sprintf("asst-%d", len(b.messages)+1),
		"type": "assistant",
		"message": map[string]interface{}{
			"content": []map[string]interface{}{
				{"type": "text", "text": content},
			},
		},
		"timestamp": time.Now().UTC().Format(time.RFC3339),
	})
	return b
}

// AddToolUse adds a tool use (Write/Edit) to the transcript.
// Returns the tool use ID for use with AddToolResult.
func (b *TranscriptBuilder) AddToolUse(toolName, filePath, content string) string {
	b.toolUseCounter++
	toolUseID := fmt.Sprintf("toolu_%d", b.toolUseCounter)

	toolUse := map[string]interface{}{
		"type": "tool_use",
		"id":   toolUseID,
		"name": toolName,
		"input": map[string]interface{}{
			"file_path": filePath,
			"content":   content,
		},
	}

	b.messages = append(b.messages, map[string]interface{}{
		"uuid": fmt.Sprintf("asst-%d", len(b.messages)+1),
		"type": "assistant",
		"message": map[string]interface{}{
			"content": []interface{}{toolUse},
		},
		"timestamp": time.Now().UTC().Format(time.RFC3339),
	})

	return toolUseID
}

// AddToolResult adds a tool result for a previous tool use.
func (b *TranscriptBuilder) AddToolResult(toolUseID string) *TranscriptBuilder {
	b.messages = append(b.messages, map[string]interface{}{
		"uuid": fmt.Sprintf("user-%d", len(b.messages)+1),
		"type": "user",
		"message": map[string]interface{}{
			"content": []map[string]interface{}{
				{
					"type":        "tool_result",
					"tool_use_id": toolUseID,
					"content":     "Success",
				},
			},
		},
		"timestamp": time.Now().UTC().Format(time.RFC3339),
	})
	return b
}

// AddTaskToolUse adds a Task tool invocation (for subagent calls).
// Returns the tool use ID for use with AddTaskToolResult.
func (b *TranscriptBuilder) AddTaskToolUse(toolUseID, prompt string) string {
	if toolUseID == "" {
		b.toolUseCounter++
		toolUseID = fmt.Sprintf("toolu_%d", b.toolUseCounter)
	}

	toolUse := map[string]interface{}{
		"type": "tool_use",
		"id":   toolUseID,
		"name": "Task",
		"input": map[string]interface{}{
			"prompt":        prompt,
			"subagent_type": "general-purpose",
		},
	}

	b.messages = append(b.messages, map[string]interface{}{
		"uuid": fmt.Sprintf("asst-%d", len(b.messages)+1),
		"type": "assistant",
		"message": map[string]interface{}{
			"content": []interface{}{toolUse},
		},
		"timestamp": time.Now().UTC().Format(time.RFC3339),
	})

	return toolUseID
}

// AddTaskToolResult adds a tool result for a Task tool invocation.
// The UUID of this message is used as the checkpoint UUID for rewind.
func (b *TranscriptBuilder) AddTaskToolResult(toolUseID, agentID string) string {
	uuid := fmt.Sprintf("user-%d", len(b.messages)+1)

	b.messages = append(b.messages, map[string]interface{}{
		"uuid": uuid,
		"type": "user",
		"message": map[string]interface{}{
			"content": []map[string]interface{}{
				{
					"type":        "tool_result",
					"tool_use_id": toolUseID,
					"content":     "Task completed by agent " + agentID,
				},
			},
		},
		"timestamp": time.Now().UTC().Format(time.RFC3339),
	})

	return uuid
}

// WriteToFile writes the transcript to a JSONL file.
func (b *TranscriptBuilder) WriteToFile(path string) error {
	// Ensure directory exists
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("failed to create directory: %w", err)
	}

	file, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	defer func() { _ = file.Close() }()

	encoder := json.NewEncoder(file)
	for _, msg := range b.messages {
		if err := encoder.Encode(msg); err != nil {
			return fmt.Errorf("failed to encode message: %w", err)
		}
	}
	return nil
}

// String returns the transcript as a JSONL string.
func (b *TranscriptBuilder) String() string {
	var result string
	var resultSb176 strings.Builder
	for _, msg := range b.messages {
		data, _ := json.Marshal(msg)
		resultSb176.WriteString(string(data) + "\n")
	}
	result += resultSb176.String()
	return result
}

// LastUUID returns the UUID of the last message added.
func (b *TranscriptBuilder) LastUUID() string {
	if len(b.messages) == 0 {
		return ""
	}
	return b.messages[len(b.messages)-1]["uuid"].(string)
}

//go:build integration

package integration

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/strategy"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// TestSubagentCheckpoints_FullFlow tests the complete subagent checkpoint flow:
// PreTask -> PostTodo (multiple times with file changes) -> PostTask
//
// This verifies:
// 1. Incremental checkpoints are created as commits during subagent execution
// 2. Only PostTodo calls with file changes create commits
// 3. PostTask creates the final task checkpoint commit
func TestSubagentCheckpoints_FullFlow(t *testing.T) {
	t.Parallel()
	RunForAllStrategies(t, func(t *testing.T, env *TestEnv, strategyName string) {
		// Create a session
		session := env.NewSession()

		// Create transcript (needed by hooks)
		session.CreateTranscript("Implement feature X", []FileChange{
			{Path: "feature.go", Content: "package main"},
		})

		// Simulate user prompt submit first (captures pre-prompt state)
		err := env.SimulateUserPromptSubmit(session.ID)
		if err != nil {
			t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
		}

		// Task tool use ID (simulates Claude's Task tool invocation)
		taskToolUseID := "toolu_01TaskABC123"

		// Step 1: PreTask - creates pre-task file
		err = env.SimulatePreTask(session.ID, session.TranscriptPath, taskToolUseID)
		if err != nil {
			t.Fatalf("SimulatePreTask failed: %v", err)
		}

		// Verify pre-task file was created
		preTaskFile := filepath.Join(env.RepoDir, ".entire", "tmp", "pre-task-"+taskToolUseID+".json")
		if _, err := os.Stat(preTaskFile); os.IsNotExist(err) {
			t.Error("pre-task file should exist after SimulatePreTask")
		}

		// Step 2: PostTodo - simulate TodoWrite calls with file changes between them
		// Note: Only PostTodo calls that detect file changes will create incremental commits

		// First TodoWrite - no file changes, should be skipped
		err = env.SimulatePostTodo(PostTodoInput{
			SessionID:      session.ID,
			TranscriptPath: session.TranscriptPath,
			ToolUseID:      "toolu_01TodoWrite001",
			Todos: []Todo{
				{Content: "Create feature file", Status: "in_progress", ActiveForm: "Creating feature file"},
				{Content: "Write tests", Status: "pending", ActiveForm: "Writing tests"},
			},
		})
		if err != nil {
			t.Fatalf("SimulatePostTodo failed for first todo: %v", err)
		}

		// Create a file change
		env.WriteFile("feature.go", "package main\n\nfunc Feature() {}\n")

		// Second TodoWrite - should create incremental checkpoint (has file changes)
		err = env.SimulatePostTodo(PostTodoInput{
			SessionID:      session.ID,
			TranscriptPath: session.TranscriptPath,
			ToolUseID:      "toolu_01TodoWrite002",
			Todos: []Todo{
				{Content: "Create feature file", Status: "completed", ActiveForm: "Creating feature file"},
				{Content: "Write tests", Status: "in_progress", ActiveForm: "Writing tests"},
			},
		})
		if err != nil {
			t.Fatalf("SimulatePostTodo failed for second todo: %v", err)
		}

		// Create another file change
		env.WriteFile("feature_test.go", "package main\n\nimport \"testing\"\n\nfunc TestFeature(t *testing.T) {}\n")

		// Third TodoWrite - should create another incremental checkpoint
		err = env.SimulatePostTodo(PostTodoInput{
			SessionID:      session.ID,
			TranscriptPath: session.TranscriptPath,
			ToolUseID:      "toolu_01TodoWrite003",
			Todos: []Todo{
				{Content: "Create feature file", Status: "completed", ActiveForm: "Creating feature file"},
				{Content: "Write tests", Status: "completed", ActiveForm: "Writing tests"},
			},
		})
		if err != nil {
			t.Fatalf("SimulatePostTodo failed for third todo: %v", err)
		}

		// Step 3: PostTask - creates final task checkpoint
		err = env.SimulatePostTask(PostTaskInput{
			SessionID:      session.ID,
			TranscriptPath: session.TranscriptPath,
			ToolUseID:      taskToolUseID,
			AgentID:        "agent-123",
		})
		if err != nil {
			t.Fatalf("SimulatePostTask failed: %v", err)
		}

		// Verify pre-task file is cleaned up
		if _, err := os.Stat(preTaskFile); !os.IsNotExist(err) {
			t.Error("Pre-task file should be removed after PostTask")
		}

		// Verify checkpoints are stored in final location (strategy-specific)
		verifyCheckpointStorage(t, env, strategyName, session.ID, taskToolUseID)
	})
}

