// verifyCheckpointStorage verifies that checkpoints are stored in the correct
// location based on the strategy type.
// Note: Incremental checkpoints are stored in separate commits during task execution,
// while the final checkpoint.json is created at PostTask time.
func verifyCheckpointStorage(t *testing.T, env *TestEnv, strategyName, sessionID, taskToolUseID string) {
	t.Helper()

	switch strategyName {
	case strategy.StrategyNameManualCommit:
		// Shadow strategy stores checkpoints in git tree on shadow branch (entire/<head-hash>)
		// We need to verify that checkpoint data exists in the shadow branch tree
		verifyShadowCheckpointStorage(t, env, sessionID, taskToolUseID)

	case strategy.StrategyNameAutoCommit:
		// Dual strategy stores metadata on orphan entire/checkpoints/v1 branch
		// Verify that commits were created (incremental + final)
		t.Logf("Note: auto-commit strategy stores checkpoints in entire/checkpoints/v1 branch")
	}
}

// verifyShadowCheckpointStorage verifies that checkpoints are stored in the shadow branch git tree.
func verifyShadowCheckpointStorage(t *testing.T, env *TestEnv, sessionID, taskToolUseID string) {
	t.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		t.Fatalf("failed to open repo: %v", err)
	}

	// Get shadow branch name using worktree-specific naming
	shadowBranchName := env.GetShadowBranchName()

	// Get shadow branch reference
	shadowRef, err := repo.Reference(plumbing.NewBranchReferenceName(shadowBranchName), true)
	if err != nil {
		t.Fatalf("shadow branch %s not found: %v", shadowBranchName, err)
	}

	// Get the commit and tree from shadow branch
	shadowCommit, err := repo.CommitObject(shadowRef.Hash())
	if err != nil {
		t.Fatalf("failed to get shadow commit: %v", err)
	}

	shadowTree, err := shadowCommit.Tree()
	if err != nil {
		t.Fatalf("failed to get shadow tree: %v", err)
	}

	// Look for task metadata in the tree
	// Path format: .entire/metadata/<session-id>/tasks/<task-id>/
	taskMetadataPrefix := ".entire/metadata/" + sessionID + "/tasks/" + taskToolUseID + "/"
	checkpointsPrefix := taskMetadataPrefix + "checkpoints/"

	foundCheckpoint := false
	foundCheckpointFiles := 0

	err = shadowTree.Files().ForEach(func(f *object.File) error {
		// Check for checkpoint file (final checkpoint)
		if f.Name == taskMetadataPrefix+paths.CheckpointFileName {
			foundCheckpoint = true
			// Verify content is valid JSON
			content, readErr := f.Contents()
			if readErr != nil {
				t.Errorf("failed to read %s: %v", paths.CheckpointFileName, readErr)
				return nil
			}
			var cp strategy.TaskCheckpoint
			if jsonErr := json.Unmarshal([]byte(content), &cp); jsonErr != nil {
				t.Errorf("%s is invalid JSON: %v", paths.CheckpointFileName, jsonErr)
			}
		}

		// Check for incremental checkpoints in checkpoints/ directory
		if strings.HasPrefix(f.Name, checkpointsPrefix) && strings.HasSuffix(f.Name, ".json") {
			foundCheckpointFiles++
			// Verify content is valid checkpoint JSON
			content, readErr := f.Contents()
			if readErr != nil {
				t.Errorf("failed to read checkpoint file %s: %v", f.Name, readErr)
				return nil
			}
			var cp strategy.SubagentCheckpoint
			if jsonErr := json.Unmarshal([]byte(content), &cp); jsonErr != nil {
				t.Errorf("checkpoint file %s is invalid JSON: %v", f.Name, jsonErr)
			}
			// Verify required fields
			if cp.Type == "" {
				t.Errorf("checkpoint file %s missing type field", f.Name)
			}
			if cp.ToolUseID == "" {
				t.Errorf("checkpoint file %s missing tool_use_id field", f.Name)
			}
		}

		return nil
	})
	if err != nil {
		t.Fatalf("failed to iterate shadow tree: %v", err)
	}

	if !foundCheckpoint {
		t.Errorf("%s not found in shadow branch tree at %s", paths.CheckpointFileName, taskMetadataPrefix+paths.CheckpointFileName)
	}

	if foundCheckpointFiles == 0 {
		t.Logf("Note: no incremental checkpoint files found in %s - they may be in earlier commits", checkpointsPrefix)
	} else {
		t.Logf("Found %d incremental checkpoint files in shadow branch tree", foundCheckpointFiles)
	}
}

	// Use parseTranscriptFromLine with offset 0 to also get totalLines
	transcript, totalLines, err = parseTranscriptFromLine(transcriptPath, 0)
	if err != nil {
		return fmt.Errorf("failed to parse transcript: %w", err)
	}
}

// Extract all prompts since last checkpoint for prompt file
allPrompts := extractUserPrompts(transcript)
promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
promptContent := strings.Join(allPrompts, "\n\n---\n\n")
if err := os.WriteFile(promptFile, []byte(promptContent), 0o600); err != nil {
	return fmt.Errorf("failed to write prompt file: %w", err)
}
fmt.Fprintf(os.Stderr, "Extracted %d prompt(s) to: %s\n", len(allPrompts), sessionDir+"/"+paths.PromptFileName)

// Extract summary
summaryFile := filepath.Join(sessionDirAbs, paths.SummaryFileName)
summary := extractLastAssistantMessage(transcript)
if err := os.WriteFile(summaryFile, []byte(summary), 0o600); err != nil {
	return fmt.Errorf("failed to write summary file: %w", err)
}
fmt.Fprintf(os.Stderr, "Extracted summary to: %s\n", sessionDir+"/"+paths.SummaryFileName)

// Get modified files from transcript (main agent + subagents).
// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
subagentsDir := filepath.Join(filepath.Dir(transcriptPath), input.SessionID, "subagents")
modifiedFiles, subagentErr := claudecode.ExtractAllModifiedFiles(transcriptPath, transcriptOffset, subagentsDir)
if subagentErr != nil {
	fmt.Fprintf(os.Stderr, "Warning: failed to extract modified files with subagents: %v\n", subagentErr)
	// Fall back to main transcript only
	modifiedFiles = extractModifiedFiles(transcript)
}

// Generate commit message from last user prompt
lastPrompt := ""
if len(allPrompts) > 0 {
	lastPrompt = allPrompts[len(allPrompts)-1]
}
commitMessage := generateCommitMessage(lastPrompt)
fmt.Fprintf(os.Stderr, "Using commit message: %s\n", commitMessage)

// Get repo root for path conversion (not cwd, since Claude may be in a subdirectory)
// Using cwd would filter out files in sibling directories (paths starting with ..)
repoRoot, err := paths.RepoRoot()
if err != nil {
	return fmt.Errorf("failed to get repo root: %w", err)
}

if preState != nil {
	fmt.Fprintf(os.Stderr, "Pre-prompt state: %d pre-existing untracked files\n", len(preState.UntrackedFiles))
}

// Compute new and deleted files (single git status call)
changes, err := DetectFileChanges(preState.PreUntrackedFiles())
if err != nil {
	fmt.Fprintf(os.Stderr, "Warning: failed to compute file changes: %v\n", err)
}

// Filter and normalize all paths (CLI responsibility)
relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
var relNewFiles, relDeletedFiles []string
if changes != nil {
	relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
	relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
}

// Check if there are any changes to commit
totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
if totalChanges == 0 {
	fmt.Fprintf(os.Stderr, "No files were modified during this session\n")
	fmt.Fprintf(os.Stderr, "Skipping commit\n")
	// Still transition phase even when skipping commit — the turn is ending.
	transitionSessionTurnEnd(sessionID)
	// Clean up state even when skipping
	if err := CleanupPrePromptState(sessionID); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", err)
	}
	return nil
}

