		}

		// Verify pre-prompt state was captured (uses entire session ID with date prefix)
		statePath := filepath.Join(env.RepoDir, ".entire", "tmp", "pre-prompt-"+modelSessionID+".json")
		if _, err := os.Stat(statePath); os.IsNotExist(err) {
